/* scq16_arch.inc.c - cpu=scq16 of the md32 arch plugin: SCQ16 (MD32 family, byte-granular packet variant).
 * Included by arch_md32.c; the decoder is scq16_decode.c (tables in scq16_opcodes.h, generated by
 * tools/gen_scq16_tables.py from isa/scq16_isa.json).
 *
 * One scq16_decode_r2 covers one INSTRUCTION:
 * a stand-alone unit, a packet {A || B} (two units executed in parallel: both read the pre-packet state) or an 8-byte
 * bundle {vec32 || s1 || s2}.  Control flow lives in the B slot of a packet (A' is never control) or in the s2 slot of a
 * bundle (short beqz/bnez); its targets are relative to the packet start.  Delay slots (.d1/.d2) count INSTRUCTIONS
 * (packets included): op->delay carries the count and op->fail the fall-through address after them when the bytes at
 * hand allow it.  ESIL: the high/medium scalar subset; a packet is emitted as A then B with the registers that B reads and
 * A writes copied to t0..t3 first (parallel semantics); delayed control flow uses the ESIL delay-slot mechanism
 * (`target,SETJT,n,SETD`: the jump is applied after n more instructions, which `aes` honours: a `.d2` transfer takes two
 * `aes` steps, the first one runs the transfer and its first slot, the second one the second slot and the jump); `do` sets
 * lc0/le0/ls0 (the back edge is not inferred).  Vector operations are the custom ESIL op `vop` (op9, A, B, F1, F2, F3
 * on the stack; registered by esilcb): the three established operations are modelled on a vector register file
 * (scq16_vu.inc.c: v.mem.ld / v.mem.st through the VU pointers vp0-vp7 and the counts va0-va7, v.move.mv as a register copy;
 * vr0-vr31 of 128 bytes exposed as four 256-bit quarters each), every other op9 has no effect; the scalar ports of the VU
 * are ESIL registers (vu, v, va, vp, vs, vb1_, vb3_, vb5_, udf, each followed by an index).
 */

#include "scq16_decode.c"
#include "scq16_vu.inc.c"

#define SCQ16_MAX_DELAY_LOOKAHEAD 3

static const char *const scq16_tmp[4] = { "t0", "t1", "t2", "t3" };

static bool scq16_cpu(RArchSession *s) {
	return s && s->config && s->config->cpu && !strcmp (s->config->cpu, "scq16");
}

static const char *scq16_sym_hex(void *user, uint32_t addr, char *buf, size_t n) {
	snprintf (buf, n, "0x%08x", (unsigned)addr);
	return buf;
}

static bool scq16_is_ctl_kind(const Scq16Alt *a) {
	return a && (a->kind == SCQ16_K_JUMP || a->kind == SCQ16_K_CALL || a->kind == SCQ16_K_BRANCH || a->kind == SCQ16_K_RET || a->kind == SCQ16_K_LOOP);
}

/* the unit that carries the control flow of the instruction (B of a packet, s2 of a bundle, the unit itself) */
static const Scq16Unit *scq16_flow_unit(const Scq16Insn *in) {
	int i;
	for (i = in->n - 1; i >= 0; i--) {
		if (scq16_is_ctl_kind (in->u[i].alt)) {
			return &in->u[i];
		}
	}
	return NULL;
}

static bool scq16_mn_is(const char *mn, const char *name) {
	const size_t len = strlen (name);
	return !strncmp (mn, name, len) && (!mn[len] || mn[len] == '.' || mn[len] == '?');
}

static int scq16_unit_type(const Scq16Unit *u) {
	const Scq16Alt *a = u->alt;
	if (!a) {
		return R_ANAL_OP_TYPE_UNK;
	}
	const char *mn = a->mn;
	switch (a->kind) {
	case SCQ16_K_JUMP:
		return scq16_mn_is (mn, "jr") ? R_ANAL_OP_TYPE_RJMP : R_ANAL_OP_TYPE_JMP;
	case SCQ16_K_CALL:
		return scq16_mn_is (mn, "jalr") ? R_ANAL_OP_TYPE_RCALL : R_ANAL_OP_TYPE_CALL;
	case SCQ16_K_BRANCH:
		return R_ANAL_OP_TYPE_CJMP;
	case SCQ16_K_RET:
		return R_ANAL_OP_TYPE_RET;
	case SCQ16_K_LOOP:
		return R_ANAL_OP_TYPE_UNK;
	case SCQ16_K_SYS:
		if (scq16_mn_is (mn, "nop")) {
			return R_ANAL_OP_TYPE_NOP;
		}
		if (scq16_mn_is (mn, "halt")) {
			return R_ANAL_OP_TYPE_TRAP;
		}
		if (scq16_mn_is (mn, "sys") || scq16_mn_is (mn, "sys41") || scq16_mn_is (mn, "ieon") || scq16_mn_is (mn, "ieoff") || scq16_mn_is (mn, "vwait")) {
			return R_ANAL_OP_TYPE_SWI;
		}
		return R_ANAL_OP_TYPE_UNK;
	case SCQ16_K_MEM:
		if (scq16_mn_is (mn, "ior") || scq16_mn_is (mn, "iow")) {
			return R_ANAL_OP_TYPE_IO;
		}
		if (mn[0] == 'l') {
			return R_ANAL_OP_TYPE_LOAD;
		}
		if (mn[0] == 's') {
			return R_ANAL_OP_TYPE_STORE;
		}
		return R_ANAL_OP_TYPE_UNK;
	case SCQ16_K_STACK:
		if (scq16_mn_is (mn, "addsp") || scq16_mn_is (mn, "add.sp")) {
			return R_ANAL_OP_TYPE_ADD;
		}
		return mn[0] == 'l' ? R_ANAL_OP_TYPE_LOAD : R_ANAL_OP_TYPE_STORE;
	case SCQ16_K_MV:
		return R_ANAL_OP_TYPE_MOV;
	case SCQ16_K_VEC:
		/* the scalar ports of the VU (vget/vbcast/vset.a/vmem.set/vins/vrd/vwr/udf) move a GPR to or from VU state */
		if (scq16_mn_is (mn, "vget") || scq16_mn_is (mn, "vbcast") || scq16_mn_is (mn, "vset") || scq16_mn_is (mn, "vmem") || scq16_mn_is (mn, "vins") || scq16_mn_is (mn, "vrd")
			|| scq16_mn_is (mn, "vwr") || scq16_mn_is (mn, "udf") || scq16_mn_is (mn, "vbcast.i")) {
			return R_ANAL_OP_TYPE_MOV;
		}
		return R_ANAL_OP_TYPE_UNK;
	default:
		break;
	}
	static const struct { const char *name; int type; } table[] = {
		{ "add", R_ANAL_OP_TYPE_ADD }, { "addsp", R_ANAL_OP_TYPE_ADD }, { "sub", R_ANAL_OP_TYPE_SUB }, { "and", R_ANAL_OP_TYPE_AND },
		{ "bclr", R_ANAL_OP_TYPE_AND }, { "or", R_ANAL_OP_TYPE_OR }, { "bset", R_ANAL_OP_TYPE_OR }, { "xor", R_ANAL_OP_TYPE_XOR },
		{ "btgl", R_ANAL_OP_TYPE_XOR }, { "btst", R_ANAL_OP_TYPE_AND }, { "sll", R_ANAL_OP_TYPE_SHL }, { "srl", R_ANAL_OP_TYPE_SHR },
		{ "sra", R_ANAL_OP_TYPE_SAR }, { "mul", R_ANAL_OP_TYPE_MUL }, { "div", R_ANAL_OP_TYPE_DIV }, { "sethi", R_ANAL_OP_TYPE_MOV },
		{ "cmov", R_ANAL_OP_TYPE_CMOV }, { "xtd", R_ANAL_OP_TYPE_CAST }, { "fxtu", R_ANAL_OP_TYPE_CAST }, { "fxts", R_ANAL_OP_TYPE_CAST },
		{ "max", R_ANAL_OP_TYPE_CMOV }, { "min", R_ANAL_OP_TYPE_CMOV }, { "clz", R_ANAL_OP_TYPE_UNK }, { "cinv", R_ANAL_OP_TYPE_UNK },
		{ "sel", R_ANAL_OP_TYPE_CMOV }, { "fup", R_ANAL_OP_TYPE_CAST },
	};
	size_t i;
	for (i = 0; i < R_ARRAY_SIZE (table); i++) {
		if (scq16_mn_is (mn, table[i].name)) {
			return table[i].type;
		}
	}
	return R_ANAL_OP_TYPE_UNK;
}

/* fall-through address after `delay` more instructions, decoded from the bytes at hand; UT64_MAX when they do not reach */
static ut64 scq16_after_delay(const ut8 *bytes, int len, ut64 addr, int size, int delay) {
	int off = size, n;
	for (n = 0; n < delay; n++) {
		Scq16Insn in;
		if (off >= len) {
			return UT64_MAX;
		}
		int r = scq16_decode_insn (bytes + off, len - off, (uint32_t)(addr + off), &in);
		if (r <= 0) {
			return UT64_MAX;
		}
		off += r;
	}
	return (ut32)(addr + off);
}

static void scq16_branch_cond(RAnalOp *op, const char *mn) {
	static const struct { const char *name; int cond; bool sign; } table[] = {
		{ "beq", R_ANAL_CONDTYPE_EQ, false }, { "bne", R_ANAL_CONDTYPE_NE, false }, { "ble", R_ANAL_CONDTYPE_LE, true },
		{ "bleu", R_ANAL_CONDTYPE_LS, false }, { "blt", R_ANAL_CONDTYPE_LT, true }, { "bltu", R_ANAL_CONDTYPE_LO, false },
		{ "beqz", R_ANAL_CONDTYPE_EQ, false }, { "beqz8", R_ANAL_CONDTYPE_EQ, false }, { "bnez", R_ANAL_CONDTYPE_NE, false },
	};
	size_t i;
	for (i = 0; i < R_ARRAY_SIZE (table); i++) {
		if (scq16_mn_is (mn, table[i].name)) {
			op->cond = table[i].cond;
			op->sign = table[i].sign;
			return;
		}
	}
}

static const char *scq16_unit_reg(const Scq16Unit *u, const char *name) {
	int i = scq16_operand_index (u, name);
	if (i < 0) {
		return NULL;
	}
	switch (u->alt->ops[i].kind) {
	case SCQ16_O_R5: case SCQ16_O_R4: case SCQ16_O_R4P: case SCQ16_O_R3P: return scq16_regs[u->vals[i] & 31];
	case SCQ16_O_CSR: return scq16_csrs[u->vals[i] & 31];
	case SCQ16_O_ACC: return scq16_accs[u->vals[i] & 31];
	default: return NULL;
	}
}

static void scq16_analyze(RAnalOp *op, const Scq16Insn *in, ut64 ret) {
	const Scq16Unit *fu = scq16_flow_unit (in);
	const Scq16Unit *u0 = &in->u[0];
	op->delay = in->delay;
	if (fu) {
		const Scq16Alt *a = fu->alt;
		op->type = scq16_unit_type (fu);
		if (fu->has_target) {
			op->jump = fu->target;
		}
		if (a->kind == SCQ16_K_BRANCH) {
			scq16_branch_cond (op, a->mn);
			op->fail = ret;
		} else if (a->kind == SCQ16_K_CALL) {
			op->fail = ret;
			const char *rn = scq16_unit_reg (fu, "rn");
			if (rn) {
				op->reg = rn;
			}
		} else if (a->kind == SCQ16_K_JUMP) {
			const char *rn = scq16_unit_reg (fu, "rn");
			if (rn) {
				op->reg = rn;
			}
			op->eob = true;
		} else if (a->kind == SCQ16_K_RET) {
			op->eob = true;
			op->reg = scq16_mn_is (a->mn, "rti") ? "ipc" : "lr";
		} else if (a->kind == SCQ16_K_LOOP) {
			/* do: the loop end (inclusive) is a reference, the body starts after the delay slots; count in a register or immediate */
			op->ptr = fu->target;
			op->direction = R_ANAL_OP_DIR_REF;
			const char *cnt = scq16_unit_reg (fu, "cnt");
			if (cnt) {
				op->reg = cnt;
			} else {
				int i = scq16_operand_index (fu, "cnt");
				op->val = i >= 0 ? (ut64)(ut32)fu->vals[i] : 0;
			}
		}
		if (in->n > 1 && !scq16_is_ctl_kind (u0->alt) && in->kind == SCQ16_I_PACKET) {
			/* the A slot executes alongside: keep the flow type */
		}
		return;
	}
	if (in->kind == SCQ16_I_PACKET || in->kind == SCQ16_I_BUNDLE) {
		/* two (or three) operations cannot be summarized by one scalar type */
		op->type = R_ANAL_OP_TYPE_UNK;
		return;
	}
	op->type = scq16_unit_type (u0);
	if (!u0->alt) {
		return;
	}
	const Scq16Alt *a = u0->alt;
	if (op->type == R_ANAL_OP_TYPE_LOAD || op->type == R_ANAL_OP_TYPE_STORE || op->type == R_ANAL_OP_TYPE_IO) {
		const char *mn = a->mn;
		op->refptr = (scq16_mn_is (mn, "lw") || scq16_mn_is (mn, "sw") || scq16_mn_is (mn, "lw.post") || scq16_mn_is (mn, "sw.post") || scq16_mn_is (mn, "lw.sp") || scq16_mn_is (mn, "sw.sp")
			|| scq16_mn_is (mn, "lw.lr") || scq16_mn_is (mn, "sw.lr") || scq16_mn_is (mn, "sw.isr") || scq16_mn_is (mn, "sw.csr") || scq16_mn_is (mn, "ior") || scq16_mn_is (mn, "iow")) ? 4 :
			(scq16_mn_is (mn, "lh") || scq16_mn_is (mn, "lhu") || scq16_mn_is (mn, "sh") || scq16_mn_is (mn, "sh.post") || scq16_mn_is (mn, "lhu.post")) ? 2 : 1;
		op->ptrsize = op->refptr;
		op->sign = scq16_mn_is (mn, "lh") || scq16_mn_is (mn, "lb");
		op->direction = op->type == R_ANAL_OP_TYPE_STORE ? R_ANAL_OP_DIR_WRITE : R_ANAL_OP_DIR_READ;
		const char *rb = scq16_unit_reg (u0, "rb");
		if (!rb) {
			rb = scq16_unit_reg (u0, "rs");
		}
		if (a->kind == SCQ16_K_STACK) {
			rb = "sp";
		}
		op->ireg = rb;
		int oi = scq16_operand_index (u0, "off");
		if (oi >= 0 && a->ops[oi].kind != SCQ16_O_R5) {
			op->disp = (st64)u0->vals[oi];
		}
		if (rb && !strcmp (rb, "sp")) {
			op->stackop = op->type == R_ANAL_OP_TYPE_LOAD ? R_ANAL_STACK_GET : R_ANAL_STACK_SET;
		}
	} else if (scq16_mn_is (a->mn, "addsp")) {
		int i = scq16_operand_index (u0, "v");
		if (i < 0) {
			i = scq16_operand_index (u0, "imm");
		}
		if (i >= 0) {
			op->stackop = R_ANAL_STACK_INC;
			op->stackptr = -(st64)u0->vals[i];
		}
	} else if (op->type == R_ANAL_OP_TYPE_MOV || scq16_mn_is (a->mn, "sethi")) {
		int i = scq16_operand_index (u0, "imm");
		if (i >= 0 && a->ops[i].kind == SCQ16_O_IMM) {
			op->val = (ut64)(ut32)u0->vals[i];
		}
	}
}

/* ESIL of the whole instruction: units in order, B/s2 with the registers written earlier in the packet read from temporaries */
static void scq16_insn_esil(RAnalOp *op, const Scq16Insn *in, ut64 ret) {
	char part[3][512];
	const char *written[3][16];
	int nw[3] = { 0, 0, 0 };
	int i, k;
	const char *const remap[4][2] = { { "", "" }, { "", "" }, { "", "" }, { "", "" } };
	const char *rm[4][2];
	int nrm = 0;
	(void)remap;
	for (i = 0; i < in->n; i++) {
		const Scq16Unit *u = &in->u[i];
		/* the override hook (experiments) counts as the unit's ESIL, also inside a packet; a unit with the empty ESIL "" (no
		 * architectural effect: nop, halt, ieon/ieoff, loopend, vwait?, sys41) never blocks the ESIL of its instruction */
		const char *ue = u->alt ? (scq16_esil_override ? scq16_esil_override (u->alt) : NULL) : NULL;
		if (u->alt && !ue) {
			ue = u->alt->esil;
		}
		if (!u->alt || !ue) {
			/* a unit without any template leaves the whole instruction without ESIL (an OPEN reading carries the marker "REF,ALT,open"
			 * from the header, so the rest of its packet keeps its ESIL) */
			if (!(u->alt && ue && !*ue)) {
				return;
			}
		}
	}
	for (i = 0; i < in->n; i++) {
		const Scq16Unit *u = &in->u[i];
		/* reads of this unit that an earlier unit of the packet writes: parallel semantics -> copy to a temporary */
		const char *reads[16];
		int nr = scq16_unit_esil_regs (u, (uint32_t)ret, false, reads, 16);
		int r, j;
		nrm = 0;
		for (r = 0; r < nr; r++) {
			for (j = 0; j < i; j++) {
				for (k = 0; k < nw[j]; k++) {
					if (!strcmp (written[j][k], reads[r]) && nrm < 4) {
						rm[nrm][0] = reads[r];
						rm[nrm][1] = scq16_tmp[nrm];
						nrm++;
					}
				}
			}
		}
		if (scq16_unit_esil (u, part[i], sizeof (part[i]), (uint32_t)ret, nrm ? (const char *const (*)[2])rm : NULL, nrm) < 0) {
			return;
		}
		nw[i] = scq16_unit_esil_regs (u, (uint32_t)ret, true, written[i], 16);
		if (nrm) {
			/* prefix: save the pre-packet values before the earlier unit writes them */
			char pre[128] = "";
			for (r = 0; r < nrm; r++) {
				char t[32];
				snprintf (t, sizeof (t), "%s%s,%s,=", r ? "," : "", rm[r][0], rm[r][1]);
				r_str_ncpy (pre + strlen (pre), t, sizeof (pre) - strlen (pre));
			}
			/* the saves go before everything: rebuild */
			char whole[1024];
			snprintf (whole, sizeof (whole), "%s", pre);
			for (j = 0; j < i; j++) {
				if (part[j][0]) {
					r_str_ncpy (whole + strlen (whole), ",", sizeof (whole) - strlen (whole));
					r_str_ncpy (whole + strlen (whole), part[j], sizeof (whole) - strlen (whole));
				}
			}
			r_strbuf_set (&op->esil, whole);
			if (part[i][0]) {
				r_strbuf_appendf (&op->esil, ",%s", part[i]);
			}
			continue;
		}
		if (i == 0) {
			r_strbuf_set (&op->esil, part[0]);
		} else if (part[i][0]) {
			if (r_strbuf_length (&op->esil)) {
				r_strbuf_appendf (&op->esil, ",%s", part[i]);
			} else {
				r_strbuf_set (&op->esil, part[i]);
			}
		}
	}
}

/* the reading class of a unit for opex: established (an operation name), provisional (a name with ?) or placeholder (a family
 * placeholder, or a vector op9 with a class but no name) */
static const char *scq16_reading_of(const Scq16Unit *u, bool isvec) {
	if (isvec) {
		const char *nm = scq16_vname[u->op9];
		return !nm ? "placeholder" : scq16_vname_firm (nm) ? "established" : "provisional";
	}
	if (u->alt->flags & SCQ16_FL_NAMED) {
		return "established";
	}
	return (u->alt->flags & SCQ16_FL_PROV) ? "provisional" : "placeholder";
}

static void scq16_fill_opex(RAnalOp *op, const Scq16Insn *in) {
	PJ *pj = pj_new ();
	int i, j;
	if (!pj) {
		return;
	}
	pj_o (pj);
	pj_ks (pj, "encoding", "scq16");
	pj_ks (pj, "shape", in->kind == SCQ16_I_PACKET ? "packet" : in->kind == SCQ16_I_BUNDLE ? "bundle" : "unit");
	if (in->kind == SCQ16_I_PACKET) {
		pj_kb (pj, "parallel", true);
	}
	pj_ki (pj, "delay", in->delay);
	pj_ka (pj, "units");
	for (i = 0; i < in->n; i++) {
		const Scq16Unit *u = &in->u[i];
		char buf[64];
		static const char *const slots[] = { "unit", "A", "B", "orphan", "s1", "s2" };
		pj_o (pj);
		pj_ks (pj, "slot", slots[u->slot]);
		pj_kn (pj, "addr", u->pc);
		pj_ki (pj, "size", u->L);
		pj_ks (pj, "mnemonic", scq16_unit_mnemonic (u, buf, sizeof (buf)));
		if (u->slot == SCQ16_S_A) {
			char hx[32] = "";
			for (j = 0; j < u->L; j++) {
				snprintf (hx + strlen (hx), sizeof (hx) - strlen (hx), "%s%02x", j ? " " : "", u->b[j]);
			}
			pj_ks (pj, "transformed", hx);
		}
		if (u->alt) {
			pj_ks (pj, "form", u->alt->form_name);
			pj_ki (pj, "form_index", u->alt->ref);
			pj_ks (pj, "kind", scq16_kind_names[u->alt->kind]);
			pj_ks (pj, "confidence", scq16_conf_names[u->alt->conf]);
			const bool isvec = u->alt == &scq16_alts[SCQ16_VEC_ALT] || u->alt == &scq16_alts[SCQ16_BUNDLE_ALT];
			/* a vector name without ? (v.move.mv, v.mem.ld, v.mem.st) is an established operation; one with ? is provisional */
			pj_kb (pj, "named", isvec ? scq16_vname_firm (scq16_vname[u->op9]) : (u->alt->flags & SCQ16_FL_NAMED) != 0);
			if ((!isvec && (u->alt->flags & SCQ16_FL_PROV)) || (isvec && scq16_vname[u->op9] && !scq16_vname_firm (scq16_vname[u->op9]))) {
				pj_kb (pj, "provisional", true);
			}
			/* the uniform marker of an OPEN reading (SCQ16_FL_OPEN: a family placeholder or a provisional name; a vector op9 without an
			 * established name) and the reading class; `hypothetical` when the ESIL is the reading of a hypothesis (SCQ16_FL_HYP) */
			pj_kb (pj, "open", isvec ? !scq16_vname_firm (scq16_vname[u->op9]) : (u->alt->flags & SCQ16_FL_OPEN) != 0);
			pj_ks (pj, "reading", scq16_reading_of (u, isvec));
			if (!isvec && (u->alt->flags & SCQ16_FL_HYP)) {
				pj_kb (pj, "hypothetical", true);
			}
			if (isvec) {
				pj_kn (pj, "op9", u->op9);
				pj_ks (pj, "vclass", scq16_vclass_names[scq16_vclass[u->op9]]);
				if (scq16_vname[u->op9]) {
					pj_ks (pj, "vname", scq16_vname[u->op9]);
				}
			}
			pj_ka (pj, "operands");
			for (j = 0; j < u->alt->nops; j++) {
				const Scq16Operand *o = &u->alt->ops[j];
				pj_o (pj);
				pj_ks (pj, "name", o->name);
				switch (o->kind) {
				case SCQ16_O_R5: case SCQ16_O_R4: case SCQ16_O_R4P: case SCQ16_O_R3P:
					pj_ks (pj, "type", "reg"); pj_ks (pj, "value", scq16_regs[u->vals[j] & 31]); break;
				case SCQ16_O_CSR:
					pj_ks (pj, "type", "csr"); pj_ks (pj, "value", scq16_csrs[u->vals[j] & 31]); break;
				case SCQ16_O_ACC:
					pj_ks (pj, "type", "acc"); pj_ks (pj, "value", scq16_accs[u->vals[j] & 31]); break;
				case SCQ16_O_DISP:
					pj_ks (pj, "type", "addr"); pj_kn (pj, "value", (ut32)u->vals[j]); break;
				default:
					pj_ks (pj, "type", "imm"); pj_kN (pj, "value", u->vals[j]); break;
				}
				pj_end (pj);
			}
			pj_end (pj);
		}
		pj_end (pj);
	}
	pj_end (pj);
	pj_end (pj);
	r_strbuf_set (&op->opex, pj_string (pj));
	pj_free (pj);
}

static bool scq16_decode_r2(RArchSession *s, RAnalOp *op, RArchDecodeMask mask) {
	const int available = op->size;
	Scq16Insn in;
	op->type = R_ANAL_OP_TYPE_ILL;
	op->size = 2;
	op->jump = op->fail = op->ptr = op->val = UT64_MAX;
	op->delay = 0;
	op->eob = false;
	if (available < 1 || !op->bytes) {
		return false;
	}
	int r = scq16_decode_insn (op->bytes, available, (ut32)op->addr, &in);
	if (r <= 0) {
		if (r == 0 && in.n == 1 && in.u[0].last_head && in.u[0].alt) {
			/* a head whose B slot is beyond the bytes at hand: report the head alone (end of a function / of the buffer) */
			in.size = in.u[0].L;
			r = in.size;
		} else {
			if (mask & R_ARCH_OP_MASK_DISASM) {
				op->mnemonic = strdup (r == 0 ? "truncated" : "invalid");
			}
			return false;
		}
	}
	op->size = r;
	op->id = in.u[0].alt ? (int)(in.u[0].alt - scq16_alts) + 1 : 0;
	ut64 ret = scq16_after_delay (op->bytes, available, op->addr, r, in.delay);
	if (ret == UT64_MAX) {
		ret = op->addr + r;   /* approximation when the delay slots are not visible */
	}
	scq16_analyze (op, &in, ret);
	if (mask & R_ARCH_OP_MASK_DISASM) {
		char txt[512];
		scq16_insn_text (&in, txt, sizeof (txt), scq16_sym_hex, NULL);
		op->mnemonic = strdup (txt);
	}
	if (mask & R_ARCH_OP_MASK_OPEX) {
		scq16_fill_opex (op, &in);
	}
	if (mask & R_ARCH_OP_MASK_ESIL) {
		scq16_insn_esil (op, &in, ret);
	}
	return true;
}

static int scq16_info(RArchSession *s, ut32 query) {
	switch (query) {
	case R_ARCH_INFO_MINOP_SIZE:
	case R_ARCH_INFO_INVOP_SIZE:
	case R_ARCH_INFO_CODE_ALIGN:
	case R_ARCH_INFO_FUNC_ALIGN:
	case R_ARCH_INFO_DATA_ALIGN:
		return 1;
	case R_ARCH_INFO_MAXOP_SIZE:
		/* a packet reaches 6 + 6 bytes; the delay-slot fall-through needs up to three more instructions */
		return 12;
	}
	return 0;
}

static char *scq16_regprofile(RArchSession *s) {
	/* ABI = public MD32: args r3-r6, return r1, sp/lr are the special registers csr14/csr15 (not r14/r15); t0-t3 are the
	 * temporaries of the parallel packet semantics; the VU scalar ports follow (vu0-31 vget lanes, v0-31 scalar shadow of
	 * vbcast, va0-7, vp0-7, vs0-15, vb1_/vb3_/vb5_ 0-31, udf0-31) */
	RStrBuf *sb = r_strbuf_new (
		"=PC pc\n=SP sp\n=LR lr\n=A0 r3\n=A1 r4\n=A2 r5\n=A3 r6\n=R0 r1\n=R1 r2\n"
		"gpr r0 .32 0 0\ngpr r1 .32 4 0\ngpr r2 .32 8 0\ngpr r3 .32 12 0\n"
		"gpr r4 .32 16 0\ngpr r5 .32 20 0\ngpr r6 .32 24 0\ngpr r7 .32 28 0\n"
		"gpr r8 .32 32 0\ngpr r9 .32 36 0\ngpr r10 .32 40 0\ngpr r11 .32 44 0\n"
		"gpr r12 .32 48 0\ngpr r13 .32 52 0\ngpr r14 .32 56 0\ngpr r15 .32 60 0\n"
		"gpr r16 .32 64 0\ngpr r17 .32 68 0\ngpr r18 .32 72 0\ngpr r19 .32 76 0\n"
		"gpr r20 .32 80 0\ngpr r21 .32 84 0\ngpr r22 .32 88 0\ngpr r23 .32 92 0\n"
		"gpr r24 .32 96 0\ngpr r25 .32 100 0\ngpr r26 .32 104 0\ngpr r27 .32 108 0\n"
		"gpr r28 .32 112 0\ngpr r29 .32 116 0\ngpr r30 .32 120 0\ngpr r31 .32 124 0\n"
		"gpr pc .32 128 0\n"
		"gpr sr .32 132 0\ngpr ipc .32 136 0\ngpr isr .32 140 0\ngpr csr3 .32 144 0\n"
		"gpr lf .32 148 0\ngpr ls0 .32 152 0\ngpr le0 .32 156 0\ngpr lc0 .32 160 0\n"
		"gpr ls1 .32 164 0\ngpr le1 .32 168 0\ngpr lc1 .32 172 0\n"
		"gpr ls2 .32 176 0\ngpr le2 .32 180 0\ngpr lc2 .32 184 0\n"
		"gpr sp .32 188 0\ngpr lr .32 192 0\n"
		"gpr csr16 .32 196 0\ngpr csr17 .32 200 0\ngpr csr18 .32 204 0\ngpr csr19 .32 208 0\n"
		"gpr csr20 .32 212 0\ngpr csr21 .32 216 0\ngpr csr22 .32 220 0\ngpr csr23 .32 224 0\n"
		"gpr csr24 .32 228 0\ngpr csr25 .32 232 0\ngpr csr26 .32 236 0\ngpr csr27 .32 240 0\n"
		"gpr csr28 .32 244 0\ngpr csr29 .32 248 0\ngpr csr30 .32 252 0\ngpr csr31 .32 256 0\n"
		"gpr a0 .64 260 0\ngpr a0l .32 260 0\ngpr a0h .32 264 0\n"
		"gpr t0 .32 268 0\ngpr t1 .32 272 0\ngpr t2 .32 276 0\ngpr t3 .32 280 0\n");
	int i, off = 284;
	const int n = scq16_vu_nregs ();
	for (i = 0; i < n; i++, off += 4) {
		r_strbuf_appendf (sb, "gpr %s .32 %d 0\n", scq16_vu_name (i), off);
	}
	off = scq16_vu_vr_profile (sb, off);   /* the vector register file vr0-vr31 (128 bytes each, four 256-bit quarters) */
	return r_strbuf_drain (sb);
}

/* custom ESIL op `vop`: a vector operation (op9, A, B, F1, F2, F3 pushed in that order, op9 on top).  The three established
 * operations are modelled (scq16_vu.inc.c: v.mem.ld / v.mem.st on the vector register file through the VU pointers, v.move.mv as a
 * register copy); every other op9 pops its operands and does nothing. */
static bool scq16_esil_vop(REsil *esil) {
	ut64 v[6];
	if (!scq16_vu_pop6 (esil, v)) {
		return false;
	}
	scq16_vu_vop_public (esil, v);
	return true;
}

/* custom ESIL op `open`: the uniform marker of an OPEN reading without semantics (a family placeholder or a provisional name
 * whose operation is not established: the table flag SCQ16_FL_OPEN; the header carries "REF,ALT,open" where the ISA table has no
 * template).  It pops its two operands and has no effect; a strict emulator may stop on it. */
static bool scq16_esil_open(REsil *esil) {
	return scq16_vu_pop_n (esil, 2, NULL);
}

static bool scq16_esilcb(RArchSession *s, REsil *esil, RArchEsilAction action) {
	if (action == R_ARCH_ESIL_ACTION_INIT && esil) {
		bool ok = r_esil_set_op (esil, "vop", scq16_esil_vop, 0, 6, R_ESIL_OP_TYPE_CUSTOM, "vector operation (op9, A, B, F1, F2, F3): v.mem.ld / v.mem.st / v.move.mv modelled on vr0-vr31, the rest no-op");
		ok &= r_esil_set_op (esil, "open", scq16_esil_open, 0, 2, R_ESIL_OP_TYPE_CUSTOM, "open reading marker (ref, alt): a form without established semantics, no effect");
		scq16_vu_esil_init (esil);   /* a write of the scalar port v{k} (vbcast / vbcast.i) is broadcast to the 64 lanes of vr{k} */
		return ok;
	}
	if (action == R_ARCH_ESIL_ACTION_FINI && esil) {
		scq16_vu_esil_fini (esil);
	}
	return true;
}

